const CAPTIONS = [{"end":1.106,"text":"Your muscles do something","start":0.192},{"end":2.598,"text":"that sounds almost impossible:","start":1.138},{"end":4.33,"text":"they send chemical messages","start":2.982},{"end":5.019,"text":"to the rest of","start":4.442},{"end":5.452,"text":"your body.","start":5.019},{"end":6.671,"text":"For a long time,","start":6.029},{"end":7.537,"text":"we mostly thought of","start":6.767},{"end":9.493,"text":"muscle as machinery\u2014it contracts,","start":7.553},{"end":10.424,"text":"moves your skeleton,","start":9.558},{"end":11.177,"text":"and lets you lift","start":10.52},{"end":11.434,"text":"things.","start":11.177},{"end":12.909,"text":"But muscle tissue has","start":11.963},{"end":13.647,"text":"another job.","start":13.006},{"end":15.491,"text":"When muscle fibers contract,","start":14.208},{"end":16.598,"text":"they can release signaling","start":15.588},{"end":18.041,"text":"proteins called myokines.","start":16.63},{"end":19.003,"text":"Think of them as","start":18.474},{"end":20.046,"text":"molecular messages.","start":19.035},{"end":22.05,"text":"Some act locally; others","start":20.559},{"end":23.574,"text":"participate in communication between","start":22.083},{"end":25.033,"text":"muscle and tissues elsewhere","start":23.67},{"end":25.498,"text":"in the body.","start":25.049},{"end":27.168,"text":"Researchers are studying how","start":26.092},{"end":28.726,"text":"this signaling network connects","start":27.232},{"end":30.397,"text":"exercise with processes involving","start":28.806},{"end":31.103,"text":"metabolism,","start":30.493},{"end":32.003,"text":"inflammation,","start":31.312},{"end":32.726,"text":"bone,","start":32.42},{"end":33.464,"text":"fat tissue,","start":32.902},{"end":34.412,"text":"and even the brain.","start":33.545},{"end":36.661,"text":"Muscle isn't simply responding","start":35.087},{"end":37.705,"text":"to your body's commands;","start":36.693},{"end":39.472,"text":"it's also sending signals","start":38.155},{"end":39.873,"text":"of its own.","start":39.504},{"end":41.351,"text":"There's still a lot","start":40.628},{"end":42.813,"text":"to learn\u2014not every proposed","start":41.351},{"end":44.098,"text":"effect of every myokine","start":42.813},{"end":44.836,"text":"has been established in","start":44.098},{"end":46.78,"text":"humans\u2014but the bigger discovery","start":44.869},{"end":49.029,"text":"is already fascinating: movement","start":46.908},{"end":49.992,"text":"is also a form","start":49.205},{"end":51.518,"text":"of biological communication.","start":50.041}];

// Single-file, deterministic whiteboard core: real stroke geometry, arc-length reveal,
// marker position on the revealed endpoint, precomputed raster tracing, timed scene data.
const C = {paper:'#ffffff', ink:'#202829', coral:'#ee766b', teal:'#12aeaa', muted:'#637372', yellow:'#f1cf57', pale:'#e9f6f3'};
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
const ease=x=>{const p=clamp(x);return p*p*(3-2*p);};
const mix=(a,b,p)=>a+(b-a)*p;
const line=(pts,color=C.ink,width=5)=>({points:pts,color,width});
const curve=(cx,cy,rx,ry,n=50)=>Array.from({length:n+1},(_,i)=>[cx+rx*Math.cos(i/n*Math.PI*2),cy+ry*Math.sin(i/n*Math.PI*2)]);
const enrich=s=>{let lengths=[0];for(let i=1;i<s.points.length;i++)lengths.push(lengths[i-1]+Math.hypot(s.points[i][0]-s.points[i-1][0],s.points[i][1]-s.points[i-1][1]));return {...s,length:lengths[lengths.length-1],lengths};};
const geometry=ss=>{let total=0;return {strokes:ss.map(s=>{const p=enrich(s);const out={...p,offset:total};total+=p.length;return out;}),total};};
const locate=(s,d)=>{const v=clamp(d,0,s.length);for(let i=1;i<s.points.length;i++){if(s.lengths[i]>=v){const p=(v-s.lengths[i-1])/Math.max(.0001,s.lengths[i]-s.lengths[i-1]);return [mix(s.points[i-1][0],s.points[i][0],p),mix(s.points[i-1][1],s.points[i][1],p)];}}return s.points[s.points.length-1];};
const ART_G=geometry(TRACES.map(s=>line(s.points,C.ink,2.5)));
const arrow=(a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],m=Math.hypot(dx,dy),ux=dx/m,uy=dy/m;return [line([a,b],C.teal,5),line([[b[0]-ux*22-uy*14,b[1]-uy*22+ux*14],b,[b[0]-ux*22+uy*14,b[1]-uy*22-ux*14]],C.teal,5)];};
const envelope=(x,y)=>[line([[x,y],[x+105,y],[x+105,y+70],[x,y+70],[x,y]]),line([[x,y],[x+52,y+39],[x+105,y]])];
