const bone=(x,y)=>[line([[x-60,y-85],[x-85,y-86],[x-101,y-65],[x-90,y-38],[x-62,y-31],[x-36,y+30],[x-49,y+57],[x-36,y+87],[x-6,y+93],[x+12,y+73],[x+30,y+82],[x+59,y+71],[x+65,y+43],[x+40,y+27],[x+11,y-35],[x+27,y-60],[x+16,y-85],[x-8,y-91],[x-26,y-72],[x-60,y-85]])];
const cell=(x,y,r=90,color=C.ink)=>[line(curve(x,y,r,r*.67),color,5),line(curve(x-20,y,24,17),color,4),line([[x+20,y-15],[x+44,y-8],[x+53,y-20],[x+65,y-6]],color,4)];
const gears=(x,y)=>{let pts=[];for(let i=0;i<=64;i++){const a=i/64*Math.PI*2,r=i%4<2?88:68;pts.push([x+Math.cos(a)*r,y+Math.sin(a)*r]);}return [line(pts),line(curve(x,y,29,29))];};
