// Pencil tip is at (98, 849) in the 1024px cutout; anchor it to the stroke endpoint.
function Marker({x,y,scale=1}) {return <g transform={`translate(${x} ${y}) scale(${scale})`}>
 <image href={HAND_EMBEDDED} x={-98*.31} y={-849*.31} width={1024*.31} height={1024*.31}/>
 </g>;}
function Draw({g,t,start,duration,tx=0,ty=0,scale=1,hand=true}){const p=clamp((t-start)/duration),dist=g.total*p;const active=g.strokes.find(s=>dist>=s.offset&&dist<s.offset+s.length);const pen=active?locate(active,dist-active.offset):null;
 return <g transform={`translate(${tx} ${ty}) scale(${scale})`}>{g.strokes.map((s,i)=>{const amount=clamp(dist-s.offset,0,s.length);if(!amount)return null;return <polyline key={i} points={s.points.map(p=>p.join(',')).join(' ')} pathLength={s.length} fill="none" stroke={s.color} strokeWidth={s.width} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={`${s.length} ${s.length}`} strokeDashoffset={s.length-amount}/>;})}{hand&&pen&&p>0&&p<1?<Marker x={pen[0]} y={pen[1]} scale={1/scale}/>:null}</g>;}
const Label=({x,y,children,size=40,color=C.ink,anchor='middle',opacity=1})=><text x={x} y={y} textAnchor={anchor} fill={color} opacity={opacity} fontFamily="'Comic Sans MS', 'Trebuchet MS', cursive" fontSize={size} fontWeight="700">{children}</text>;
function Art({t,start=0,duration=3.5,x=150,y=195,scale=1.28,colorAt=3.9}){const color=ease((t-colorAt)/.75);return <g><image href={ART_EMBEDDED} x={x} y={y} width={720*scale} height={540*scale} opacity={color}/><g opacity={1-color}><Draw g={ART_G} t={t} start={start} duration={duration} tx={x} ty={y} scale={scale}/></g></g>;}
const escapeXml=v=>String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
function svgMarkup(node){if(node==null||node===false)return '';if(Array.isArray(node))return node.map(svgMarkup).join('');if(typeof node!=='object')return escapeXml(node);if(node.type===React.Fragment)return svgMarkup(node.props.children);if(typeof node.type==='function')return svgMarkup(node.type(node.props));const attrs=Object.entries(node.props).filter(([k,v])=>k!=='children'&&k!=='key'&&v!=null).map(([k,v])=>` ${k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()).replace('view-box','viewBox').replace('path-length','pathLength')}="${escapeXml(v)}"`).join('');return `<${node.type}${attrs}>${svgMarkup(node.props.children)}</${node.type}>`;}
const title=(text,sub)=> <><Label x={960} y={118} size={66}>{text}</Label><Label x={960} y={174} size={28} color={C.muted}>{sub}</Label></>;
export default function WhiteboardMuscle(){const f=useCurrentFrame(),{fps}=useVideoConfig(),t=f/fps;const caption=CAPTIONS.find(c=>t>=c.start&&t<=c.end+.12);let board;
 if(t<5.9){board=<>{title('Your muscles have a secret.','MORE THAN MOVEMENT')}<Art t={t}/><Draw g={geometry([...arrow([1150,470],[1490,470]),...envelope(1490,435)])} t={t} start={2.98} duration={1.25}/><Label x={1540} y={605} size={40} opacity={ease((t-4)/.4)}>chemical messages</Label><Label x={590} y={840} size={32} color={C.coral} opacity={ease((t-3.7)/.4)}>MUSCLE</Label></>;}
 else if(t<11.9){board=<>{title('The old picture: a machine','CONTRACT. MOVE. LIFT.')}<Draw g={lifter} t={t} start={6} duration={2.1} tx={220} ty={145} scale={1.08}/><Label x={735} y={860} color={C.coral} opacity={ease((t-8)/.4)}>movement</Label><Draw g={geometry(arrow([1240,510],[1550,510]))} t={t} start={9.1} duration={.7}/><Label x={1580} y={620} size={95} opacity={ease((t-10.1)/.4)}>…?</Label></>;}
 else if(t<20.4){const squeeze=1-.05*Math.sin(clamp((t-14.2)/1.6)*Math.PI);board=<>{title('Another job: sending signals','WHEN MUSCLE FIBERS CONTRACT')}<g transform={`translate(${(1-squeeze)*960} 0) scale(${squeeze} 1)`}><Draw g={fibers} t={t} start={12} duration={2} tx={180} ty={180} scale={1.5}/></g><Label x={720} y={735} size={72} color={C.teal} opacity={ease((t-16.63)/.5)}>MYOKINES</Label><Label x={1210} y={830} size={35} opacity={ease((t-18.47)/.5)}>molecular messages, not tiny machines.</Label>{Array.from({length:5},(_,i)=>{const p=clamp((t-15.5-i*.2)/2);return p>0?<circle key={i} cx={1060+p*310} cy={510+Math.sin(p*Math.PI*2+i)*34} r={10} fill={C.teal} opacity={1-p*.55}/>:null;})}</>;}
 else if(t<35){board=<>{title('One muscle. A whole conversation.','LOCAL SIGNALS + DISTANT TISSUES')}<Draw g={network} t={t} start={20.5} duration={6.4}/><Label x={910} y={445} size={28}>muscle</Label><Label x={1465} y={355} size={32} opacity={ease((t-26)/.6)}>brain</Label><Label x={1500} y={650} size={32} opacity={ease((t-27)/.6)}>bone</Label><Label x={1190} y={880} size={32} opacity={ease((t-28)/.6)}>fat tissue</Label><Label x={390} y={400} size={32} opacity={ease((t-27.5)/.6)}>metabolism</Label><Label x={398} y={880} size={32} opacity={ease((t-29)/.6)}>inflammation</Label>{t>30&&[[-.8,0],[.8,-.6],[.85,.1],[.5,.8],[-.8,.6]].map(([dx,dy],i)=>{const p=((t-30)*.65+i*.19)%1;return <circle key={i} cx={910+dx*560*p} cy={460+dy*440*p} r={8} fill={C.coral} opacity={Math.sin(p*Math.PI)}/>;})}</>;}
 else if(t<40.55){board=<>{title('Not just taking orders.','MUSCLE SENDS SIGNALS OF ITS OWN')}<Draw g={geometry(brain(440,365))} t={t} start={35.05} duration={.8}/><Label x={440} y={540} size={35}>commands</Label><Art t={t} start={36.05} duration={1.5} x={880} y={210} scale={.9} colorAt={37.7}/><Draw g={geometry(arrow([575,405],[920,405]))} t={t} start={35.8} duration={.65} hand={false}/><Draw g={geometry(arrow([975,590],[560,590]))} t={t} start={38.1} duration={.8}/><Label x={730} y={750} size={56} color={C.teal} opacity={ease((t-38.7)/.5)}>a two-way conversation</Label></>;}
 else if(t<46.8){board=<>{title('Fascinating ≠ fully proven','SCIENCE IS STILL FILLING IN THE PICTURE')}<Draw g={notebook} t={t} start={40.65} duration={1.7}/><Label x={934} y={764} size={43} color={C.teal} opacity={ease((t-42)/.5)}>a real signaling network</Label><Label x={934} y={830} size={33} color={C.coral} opacity={ease((t-43.8)/.5)}>not every effect established in humans</Label></>;}
 else {const p=ease((t-46.85)/2);board=<>{title('Movement is communication.','THE BIGGER DISCOVERY')}<Art t={t} start={46.8} duration={1.1} x={120} y={230} scale={.9} colorAt={48}/><Draw g={geometry([...arrow([840,460],[1150,460]),...envelope(1165,427),...arrow([1320,460],[1540,460]),...brain(1640,445)])} t={t} start={47.4} duration={1.8}/><Label x={950} y={850} size={58} color={C.teal} opacity={p}>Your muscles have something to say.</Label></>;}
 const svg=<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1920 1080" width="1920" height="1080"><rect width="1920" height="1080" fill={C.paper}/>{board}<path d="M160 949 L1760 949" stroke={C.pale} strokeWidth="3"/>{caption?<text x="960" y="1008" textAnchor="middle" fill={C.ink} fontFamily="Arial, sans-serif" fontSize="36">{caption.text}</text>:null}<rect x="160" y="1046" width={1600*clamp(t/51.84)} height="5" rx="2" fill={C.teal}/></svg>;
 return <AbsoluteFill style={{backgroundColor:C.paper}}><Audio src={VOICE}/><Img src={'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svgMarkup(svg))} style={{width:'100%',height:'100%'}}/></AbsoluteFill>;
}
